mapper.select:
select id, discipline_record_id as disciplineRecordId, action_type as actionType,
       target_type as targetType, target_id as targetId, execution_status as executionStatus,
       result_message as resultMessage, create_time as createTime, update_time as updateTime, is_delete as isDelete
from basket_discipline_execution_detail
where discipline_record_id = #{disciplineRecordId}
  and action_type = #{actionType}
  and target_type = #{targetType}
  and target_id = #{targetId}
  and is_delete = 0
limit 1
